// Package wslenv detects WSL2 and its networking mode from plain facts.
package wslenv

import "net/netip"

// Mode is the WSL2 networking mode.
type Mode int

const (
	// ModeUndetermined is the zero value: the mode could not be established.
	ModeUndetermined Mode = iota
	// ModeNAT is the default WSL2 mode (virtual switch).
	ModeNAT
	// ModeMirrored mirrors the Windows interfaces into the distro.
	ModeMirrored
)

// Facts are the raw observations Classify decides from.
type Facts struct {
	DistroName        string
	OSRelease         string
	NetworkingMode    string
	NetworkingModeErr error
	Interfaces        []string
	ProcNetRoute      []byte
}

// Info is the classification of Facts.
type Info struct {
	WSL2         bool
	Mode         Mode
	NATInterface string
	// NATGateway is the zero Addr when unknown (mode not NAT, or no usable
	// default route): consumers must test NATGateway.IsValid().
	NATGateway netip.Addr
}
package wslenv

import (
	"slices"
	"strings"
)

// mirroredInterface exists in the distro only under mirrored networking.
const mirroredInterface = "loopback0"

// Classify turns Facts into Info. A zero Info means "not WSL2".
func Classify(f Facts) Info {
	if !isWSL(f) || !strings.Contains(strings.ToUpper(f.OSRelease), "WSL2") {
		return Info{}
	}
	info := Info{WSL2: true}
	if f.NetworkingModeErr != nil {
		return info
	}
	hasLoopback0 := slices.Contains(f.Interfaces, mirroredInterface)
	switch strings.ToLower(strings.TrimSpace(f.NetworkingMode)) {
	case "nat":
		if hasLoopback0 {
			return info
		}
		info.Mode = ModeNAT
		if iface, gw, ok := defaultGateway(f.ProcNetRoute); ok {
			info.NATInterface = iface
			info.NATGateway = gw
		}
	case "mirrored":
		if !hasLoopback0 {
			return info
		}
		info.Mode = ModeMirrored
	}
	return info
}

// isWSL reports whether the facts describe a WSL distro (1 or 2). Either signal
// suffices: WSL_DISTRO_NAME is empty under `env -i` or from a service, and
// osrelease alone then identifies WSL.
func isWSL(f Facts) bool {
	return f.DistroName != "" || strings.Contains(strings.ToLower(f.OSRelease), "microsoft")
}
package wslenv

import (
	"context"
	"net"
	"os"
	"runtime"
)

const (
	osReleasePath = "/proc/sys/kernel/osrelease"
	procRoutePath = "/proc/net/route"
)

// Probe is the set of system reads Gather performs. Tests replace every field.
type Probe struct {
	GOOS           string
	Getenv         func(string) string
	ReadFile       func(string) ([]byte, error)
	InterfaceNames func() ([]string, error)
	NetworkingMode func(ctx context.Context) (string, error)
}

// SystemProbe returns the Probe backed by the real system.
func SystemProbe() Probe {
	return Probe{
		GOOS:           runtime.GOOS,
		Getenv:         os.Getenv,
		ReadFile:       os.ReadFile,
		InterfaceNames: interfaceNames,
		NetworkingMode: wslinfoNetworkingMode,
	}
}

// interfaceNames lists the names of this machine's network interfaces.
func interfaceNames() ([]string, error) {
	ifaces, err := net.Interfaces()
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(ifaces))
	for _, i := range ifaces {
		names = append(names, i.Name)
	}
	return names, nil
}

// Gather collects Facts through p. It reads nothing off Linux, and reads the
// WSL-only facts (interfaces, routes, networking mode) only under WSL. A read
// error leaves the matching fact empty.
func Gather(ctx context.Context, p Probe) Facts {
	if p.GOOS != "linux" {
		return Facts{}
	}
	f := Facts{DistroName: p.Getenv("WSL_DISTRO_NAME")}
	if b, err := p.ReadFile(osReleasePath); err == nil {
		f.OSRelease = string(b)
	}
	if !isWSL(f) {
		return f
	}
	if names, err := p.InterfaceNames(); err == nil {
		f.Interfaces = names
	}
	if b, err := p.ReadFile(procRoutePath); err == nil {
		f.ProcNetRoute = b
	}
	// A probe that ignores ctx must still report a cancelled context.
	if err := ctx.Err(); err != nil {
		f.NetworkingModeErr = err
		return f
	}
	f.NetworkingMode, f.NetworkingModeErr = p.NetworkingMode(ctx)
	return f
}

// Detect is Classify(Gather(ctx, SystemProbe())).
func Detect(ctx context.Context) Info { return Classify(Gather(ctx, SystemProbe())) }

